import 'dart:ui';import 'package:flutter/services.dart';import 'package:google_maps_flutter/google_maps_flutter.dart';import 'package:flutter/material.dart';import 'package:zan/Core/Utils/Extensions/context_extension.dart';import 'dart:ui' as ui;import '../../../../../../../Core/Services/Map/location_service.dart';import '../../../../../../../Core/Services/Map/markers_model.dart';// import 'dart:typed_data' as typed_data;class MapSample extends StatefulWidget {  const MapSample({super.key});  @override  State<MapSample> createState() => MapSampleState();}class MapSampleState extends State<MapSample> {  static const CameraPosition _kGooglePlex = CameraPosition(    target: LatLng(27.669593268876408, 30.789149139355608), // point of the map    zoom: 6,  );  final Set<Marker> _markers = {};  bool isFirstCall = true;  late LocationService locationService;  // world view O -> 1  // country view 4 -> 6  // city view 10 -> 12  // street  view  13 -> 17  // building view 18 -> 20  GoogleMapController? mapController;  @override  void initState() {    locationService = LocationService();    super.initState();  }  @override  Widget build(BuildContext context) {    return Scaffold(      body: GoogleMap(        markers: _markers,        buildingsEnabled: false,        mapType: MapType.terrain,        initialCameraPosition: _kGooglePlex,        onMapCreated: (GoogleMapController controller) {          mapController = controller;          updateCurrentLocation();          initMarkers();        },      ),    );  }  void updateCurrentLocation() async {    try {      var data = await locationService.getLocation();      LatLng currentLocation = LatLng(data.latitude!, data.longitude!);      MarkersModel.lat = data.latitude!;      MarkersModel.lng = data.longitude!;      final  BitmapDescriptor assetName = await _createCustomMarker( "Assets/Png/location.png",5);      var marker = Marker(        markerId: MarkerId('MyLocation'),        position: currentLocation,        icon: assetName      );      setState(() {        _markers.add(marker);      });      mapController?.animateCamera(        CameraUpdate.newCameraPosition(          CameraPosition(target: currentLocation, zoom: 17),        ),      );    } on LocationServiceException {      // TODO:    } on LocationPermissionException {      // TODO :    } catch (e) {      // TODO:    }  }  Future<BitmapDescriptor> _createCustomMarker(      String imagePath, double rating) async {    final ui.PictureRecorder pictureRecorder = ui.PictureRecorder();    final Canvas canvas = Canvas(pictureRecorder);    final double size = 200;    // download the image    final ByteData data = await rootBundle.load(imagePath);    final ui.Codec codec = await ui        .instantiateImageCodec(data.buffer.asUint8List(), targetWidth: 200);    final ui.FrameInfo frameInfo = await codec.getNextFrame();    final ui.Image userImage = frameInfo.image;    final Paint paint = Paint();    canvas.drawImage(userImage, Offset(0, 0), paint);    // drawing background for evaluation    final Paint ratingBgPaint = Paint()..color = Colors.white;    final ratingRect = Rect.fromLTWH(30, 100, 75, 40);    canvas.drawRect(ratingRect, ratingBgPaint);    // rating fee star icon    final textPainter = TextPainter(textDirection: TextDirection.ltr);    textPainter.text = TextSpan(      text: rating.toString(),      style: TextStyle(          fontSize: 16, color: Colors.black, fontWeight: FontWeight.bold),    );    textPainter.layout();    textPainter.paint(canvas, Offset(50, 105));    final starIcon = Icons.star;    final starPainter = TextPainter(textDirection: TextDirection.ltr);    starPainter.text = TextSpan(      text: String.fromCharCode(starIcon.codePoint),      style: TextStyle(          fontSize: 20, color: Colors.amber, fontFamily: starIcon.fontFamily),    );    starPainter.layout();    starPainter.paint(canvas, Offset(40, 13));    final ui.Image finalImage = await pictureRecorder        .endRecording()        .toImage(size.toInt(), size.toInt());    final ByteData? byteData =        await finalImage.toByteData(format: ui.ImageByteFormat.png);    final Uint8List uint8List = byteData!.buffer.asUint8List();    return BitmapDescriptor.fromBytes(uint8List);  }  void initMarkers() async {    final  BitmapDescriptor assetName = await _createCustomMarker( "Assets/Png/carpenter.png",5);    final value = MarkersModel.markers        .map(          (e) => Marker(            infoWindow: InfoWindow(              title: e.title,            ),            onTap: (){              context.buildCustomBottomSheet();            },            icon: assetName,            markerId: MarkerId(e.id),            position: e.markerPosition,          ),        )        .toSet();    _markers.addAll(value);    setState(() {});  }}